def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not intervals:
        return []

    # Normalize intervals so that start <= end
    normalized = []
    for interval in intervals:
        if len(interval) != 2:
            raise ValueError(f"Each interval must have exactly two elements: {interval!r}")
        a, b = interval
        start, end = (a, b) if a <= b else (b, a)
        normalized.append((start, end))

    # Sort by start, then by end
    normalized.sort(key=lambda iv: (iv[0], iv[1]))

    merged = [normalized[0]]
    for start, end in normalized[1:]:
        last_start, last_end = merged[-1]
        # Overlapping or touching (closed intervals): merge when start <= last_end
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged
